        try self.voiceContainer.paint(cx + self.x, cy + self.y, canvas)
        canvas.color = self.resources.mainGlyphColor
        try self._postBeatGlyphs.paint(cx + self.x, cy + self.y, canvas)
        try self._paintMultiSystemSlurs(cx, cy, canvas)
    }

    private func _paintMultiSystemSlurs(_ cx: Double, _ cy: Double, _ canvas: any ICanvas) throws {
        let multiSystemSlurs: List<ContinuationTieGlyph>? = self._multiSystemSlurs
        if !TypeHelper.isTruthy(multiSystemSlurs) {
            return
        }
        for slur in multiSystemSlurs! {
            try slur.paint(cx, cy, canvas)
        }
    }

    internal func paintBackground(_ cx: Double, _ cy: Double, _ canvas: any ICanvas) throws {
        self.layoutingInfo.paint(cx + self.x + self._preBeatGlyphs.x + self._preBeatGlyphs.width, cy + self.y + self.height, canvas)
    }

    public func buildBoundingsLookup(_ masterBarBounds: MasterBarBounds, _ cx: Double, _ cy: Double) throws {
        let barBounds: BarBounds = BarBounds()
        barBounds.bar = self.bar
        barBounds.visualBounds = Bounds()
        barBounds.visualBounds.x = cx + self.x
        barBounds.visualBounds.y = cy + self.y
        barBounds.visualBounds.w = self.width
        barBounds.visualBounds.h = self.height
        barBounds.realBounds = Bounds()
        barBounds.realBounds.x = cx + self.x
        barBounds.realBounds.y = cy + self.y
        barBounds.realBounds.w = self.width
        barBounds.realBounds.h = self.height
        masterBarBounds.addBar(barBounds)
        try self.voiceContainer.buildBoundingsLookup(barBounds, cx + self.x, cy + self.y)
    }

    internal func addPostBeatGlyph(_ g: Glyph) throws {
        try self._postBeatGlyphs.addGlyph(g)
    }

    internal func createPreBeatGlyphs() throws {
        self.wasFirstOfStaff = self.isFirstOfStaff
    }

    internal func createBeatGlyphs() throws {
        if TypeHelper.isTruthy(self.additionalMultiRestBars) {
            let container: MultiBarRestBeatContainerGlyph = MultiBarRestBeatContainerGlyph()
            try self.addBeatGlyph(container)
        } else {
            for index in self.bar.filledVoices {
                try self.createVoiceGlyphs(self.bar.voices[(index).toInt()])
            }
        }
        try self.voiceContainer.doLayout()
        if self.topEffects.isLinkedToPreviousRenderer || self.bottomEffects.isLinkedToPreviousRenderer {
            self.isLinkedToPrevious = true
        }
    }

    internal func createVoiceGlyphs(_ voice: Voice) throws {
        try self.topEffects.createVoiceGlyphs(voice)
        try self.bottomEffects.createVoiceGlyphs(voice)
    }

    internal func createPostBeatGlyphs() throws {
    }

    public var beatGlyphsStart: Double {
        get {
            return self.voiceContainer.x
        }
    }

    public var postBeatGlyphsStart: Double {
        get {
            return self._postBeatGlyphs.x
        }
    }

    public func getBeatX(_ beat: Beat, _ requestedPosition: BeatXPosition = BeatXPosition.PreNotes, _ useSharedSizes: Bool = false) -> Double {
        return self.beatGlyphsStart + self.voiceContainer.getBeatX(beat, requestedPosition, useSharedSizes)
    }

    public func getRatioPositionX(_ ratio: Double) -> Double {
        let firstOnNoteX: Double = self.bar.isEmpty ? self.beatGlyphsStart : self.getBeatX(self.bar.voices[0].beats[0], BeatXPosition.MiddleNotes)
        let x: Double = firstOnNoteX
        let w: Double = self.postBeatGlyphsStart - firstOnNoteX
        return x + w * ratio
    }

    public func getNoteX(_ note: Note, _ requestedPosition: NoteXPosition) throws -> Double {
        return try self.beatGlyphsStart + self.voiceContainer.getNoteX(note, requestedPosition)
    }

    public func getNoteY(_ note: Note, _ requestedPosition: NoteYPosition) throws -> Double {
        return try self.voiceContainer.y + +self.voiceContainer.getNoteY(note, requestedPosition)
    }

    public func getRestY(_ beat: Beat, _ requestedPosition: NoteYPosition) throws -> Double {
        return try self.voiceContainer.y + +self.voiceContainer.getRestY(beat, requestedPosition)
    }

    public func reLayout() throws {
        self.topEffects.height = 0.0
        self.bottomEffects.height = 0.0
        try self.updateSizes()
        if (self.wasFirstOfStaff && !self.isFirstOfStaff) || (!self.wasFirstOfStaff && self.isFirstOfStaff) {
            try self.recreatePreBeatGlyphs()
        }
        try self._registerLayoutingInfo()
        try self._registerOverlayRods()
        if !self._layoutInvariantCached {
            try self.calculateOverflows(0.0, self.height)
            self._layoutInvariantCached = true
        }
    }

    internal func recreatePreBeatGlyphs() throws {
        self._layoutInvariantCached = false
        self._preBeatGlyphs = LeftToRightLayoutingGlyphGroup()
        self._preBeatGlyphs.renderer = self
        try self.createPreBeatGlyphs()
    }

    internal func paintSimileMark(_ cx: Double, _ cy: Double, _ canvas: any ICanvas) throws {
        let _using0: (any Disposable)? = ElementStyleHelper.voice(canvas, (VoiceSubElement.Glyphs as! VoiceSubElement), self.bar.voices[0], true)
        defer {
            _using0?.dispose()
        }
        switch self.bar.simileMark {
        case SimileMark.Simple:
            try canvas.beginGroup(BeatContainerGlyph.getGroupId(self.bar.voices.jsElement(0).beats[0]))
            try CanvasHelper.fillMusicFontSymbolSafe(canvas, cx + self.x + self.width / 2.0, cy + self.y + self.height / 2.0, 1.0, MusicFontSymbol.Repeat1Bar, true)
            canvas.endGroup()
        case SimileMark.SecondOfDouble:
            try canvas.beginGroup(BeatContainerGlyph.getGroupId(self.bar.voices.jsElement(0).beats[0]))
            try canvas.beginGroup(BeatContainerGlyph.getGroupId(jsNonNull(self.bar.previousBar).voices.jsElement(0).beats[0]))
            try CanvasHelper.fillMusicFontSymbolSafe(canvas, cx + self.x, cy + self.y + self.height / 2.0, 1.0, MusicFontSymbol.Repeat2Bars, true)
            canvas.endGroup()
            canvas.endGroup()
        default:
            break
        }
    }

    open func completeBeamingHelper(_ _helper: BeamingHelper) throws {
    }
}

/**
 * Lists the different position modes for
 */
internal enum NoteYPosition: Int, IAlphaTabEnum, CaseIterable {
    /**
     * Gets the note y-position on top of the note stem or tab number.
     */
    case TopWithStem = 0
    /**
     * Gets the note y-position on top of the note head or tab number.
     */
    case Top = 1
    /**
     * Gets the note y-position on the center of the note head or tab number.
     */
    case Center = 2
    /**
     * Gets the note y-position on the bottom of the note head or tab number.
     */
    case Bottom = 3
    /**
     * Gets the note y-position on the bottom of the note stem or tab number.
     */
    case BottomWithStem = 4
    /**
     * The position where the upwards stem should be placed.
     */
    case StemUp = 5
    /**
     * The position where the downwards stem should be placed.
     */
    case StemDown = 6
}

/**
 * Lists the different position modes for
 */
internal enum NoteXPosition: Int, IAlphaTabEnum, CaseIterable {
    /**
     * Gets the note x-position on left of the note head or tab number.
     */
    case Left = 0
    /**
     * Gets the note x-position on the center of the note head or tab number.
     */
    case Center = 1
    /**
     * Gets the note x-position on the right of the note head or tab number.
     */
    case Right = 2
}
